// ----- skilling sounds: one short beat per action, made in code. Each varies a little in pitch so repeats don't grate -----
function sfx(build){ const ctx = audio(); if (!ctx) return; const out = ctx.createGain(); out.connect(sfxOut(ctx)); build(ctx, ctx.currentTime + 0.005, out); }
// filtered noise with an attack and a decay
function nz(ctx, out, t, dur, type, f0, f1, q, vol, att, dec){
  const n = ctx.createBufferSource(); n.buffer = noiseBuffer(ctx, dur); const f = ctx.createBiquadFilter(); f.type = type;
  f.frequency.setValueAtTime(f0, t); f.frequency.linearRampToValueAtTime(f1, t + dur); f.Q.value = q;
  const g = ctx.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(vol, t + att); g.gain.exponentialRampToValueAtTime(0.0001, t + Math.min(dur, att + dec));
  n.connect(f); f.connect(g); g.connect(out); n.start(t); n.stop(t + dur);
}
// ringing metal: a few partials that die away
function ring(ctx, out, t, parts, dur, vol){ for (const [f, g0, k] of parts) { const o = ctx.createOscillator(), g = ctx.createGain(); o.frequency.value = f;
  g.gain.setValueAtTime(vol * g0, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur / (k || 1)); o.connect(g); g.connect(out); o.start(t); o.stop(t + dur + 0.02); } }
const wobble = () => 0.95 + Math.random() * 0.1;
// mining: a bright pick strike, a gritty crunch of stone, a low knock and a few falling chips
function mineSound(){ sfx((ctx, t, out) => { const p = wobble(); out.gain.value = 0.6;
  ring(ctx, out, t, [[1650 * p, 1, 1], [3420 * p, 0.5, 1.6], [5280 * p, 0.3, 2.2]], 0.3, 0.32);
  nz(ctx, out, t, 0.12, 'bandpass', 2100, 1800, 0.9, 0.9, 0.001, 0.1);
  nz(ctx, out, t, 0.1, 'lowpass', 320, 320, 0.7, 0.8, 0.001, 0.08);
  for (let i = 0; i < 5; i++) nz(ctx, out, t + 0.07 + Math.random() * 0.25, 0.03, 'bandpass', 2500 + Math.random() * 1700, 3000, 2.5, 0.15 + Math.random() * 0.2, 0.001, 0.025); }); }
// the anvil: one ringing clang per hammer strike
function anvilSound(){ sfx((ctx, t, out) => { const p = wobble(); out.gain.value = 0.55;
  ring(ctx, out, t, [[950 * p, 1, 1], [2410 * p, 0.55, 1.5], [3780 * p, 0.35, 2], [5130 * p, 0.2, 2.6]], 0.5, 0.3);
  nz(ctx, out, t, 0.05, 'lowpass', 1200, 1200, 0.7, 0.7, 0.001, 0.04); }); }
// smelting: a bellows whoosh flaring into fire, then a short hiss
function smeltSound(){ sfx((ctx, t, out) => { out.gain.value = 0.6;
  nz(ctx, out, t, 0.45, 'bandpass', 300, 1100, 0.8, 0.5, 0.12, 0.3);
  nz(ctx, out, t + 0.18, 0.55, 'lowpass', 500, 450, 0.7, 0.8, 0.05, 0.45);
  nz(ctx, out, t + 0.5, 0.3, 'highpass', 4200, 4200, 0.7, 0.25, 0.01, 0.25); }); }
const clinkSound = smeltSound;   // older name for the furnace sound
// the wood groaning as it starts to tip over
function creakSound(dur){
  const ctx = audio(); if (!ctx) return; const t = ctx.currentTime;
  const o = ctx.createOscillator(), lp = ctx.createBiquadFilter(), g = ctx.createGain();
  o.type = 'sawtooth'; o.frequency.setValueAtTime(110, t); o.frequency.linearRampToValueAtTime(160, t + dur);
  lp.type = 'lowpass'; lp.frequency.value = 500;
  g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.22, t + dur * 0.5); g.gain.linearRampToValueAtTime(0.0001, t + dur);
  o.connect(lp); lp.connect(g); g.connect(sfxOut(ctx)); o.start(t); o.stop(t + dur + 0.05);
}
// the trunk hitting the ground: a deep thud with a little rustle
function fallSound(){
  const ctx = audio(); if (!ctx) return; const t = ctx.currentTime;
  const src = ctx.createBufferSource(); src.buffer = noiseBuffer(ctx, 0.6);
  const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 400;
  const g = ctx.createGain(); g.gain.setValueAtTime(0.8, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.6);
  src.connect(lp); lp.connect(g); g.connect(sfxOut(ctx)); src.start(t); src.stop(t + 0.6);
  const o = ctx.createOscillator(), og = ctx.createGain();
  o.frequency.setValueAtTime(70, t); o.frequency.exponentialRampToValueAtTime(35, t + 0.4);
  og.gain.setValueAtTime(0.7, t); og.gain.exponentialRampToValueAtTime(0.001, t + 0.45);
  o.connect(og); og.connect(sfxOut(ctx)); o.start(t); o.stop(t + 0.5);
}

// which arm pose a point in the swing shows: wind up (first 40%), strike (40-55%), recover (the rest)

// ----- chopping: click a tree to walk to it, chop for a few seconds, and it falls, leaves a stump, and grows back -----
const CHOP_FRAMES = 180;          // about 3 seconds of chopping
const REGROW_FRAMES = 1500;       // about 25 seconds before the tree grows back
const chop = { rec: null, t: 0 }; // the tree being chopped, and how long we have been at it
const felledTrees = [];           // { rec, wait } for trees waiting to grow back
function showToast(msg){
  const t = document.getElementById('toast');
  t.textContent = msg; t.style.display = 'block';
  clearTimeout(showToast.timer); showToast.timer = setTimeout(() => { t.style.display = 'none'; }, Math.max(2400, Math.min(9000, 1200 + String(msg).length * 45)));   /* longer messages stay up longer */
}
function addXp(skill, amt){
  const before = levelOf(SKILL_XP[skill]);
  SKILL_XP[skill] += amt; renderStats();
  const after = levelOf(SKILL_XP[skill]);
  if (after > before) { if (!quietLevelUps) levelUpSound(); showToast(`Congratulations! Your ${skill} level is now ${after}.`); }
}
// a little brass fanfare: "duh duh du duhhhh"
function levelUpSound(){
  const ctx = audio(); if (!ctx) return; const t0 = ctx.currentTime + 0.02;
  const out = ctx.createGain(); out.gain.value = 0.22; out.connect(sfxOut(ctx));
  const notes = [[523.25, 0, 0.14], [523.25, 0.17, 0.14], [659.25, 0.34, 0.12], [783.99, 0.5, 1.1]];   // C C E G
  for (const [f, at, len] of notes) {
    for (const [mul, type, vol] of [[1, 'sawtooth', 0.5], [1.005, 'square', 0.25], [0.5, 'triangle', 0.6]]) {
      const o = ctx.createOscillator(), g = ctx.createGain(), lp = ctx.createBiquadFilter();
      o.type = type; o.frequency.value = f * mul; lp.type = 'lowpass'; lp.frequency.value = 2200;
      const s = t0 + at;
      g.gain.setValueAtTime(0, s); g.gain.linearRampToValueAtTime(vol, s + 0.02);
      g.gain.setValueAtTime(vol * 0.8, s + len * 0.6); g.gain.exponentialRampToValueAtTime(0.001, s + len + 0.15);
      if (len > 0.5) { const lfo = ctx.createOscillator(), lg = ctx.createGain(); lfo.frequency.value = 5.5; lg.gain.value = 4; lfo.connect(lg); lg.connect(o.frequency); lfo.start(s + 0.2); lfo.stop(s + len + 0.2); }   // vibrato on the long note
      o.connect(lp); lp.connect(g); g.connect(out); o.start(s); o.stop(s + len + 0.2);
    }
  }
}
function cancelChop(){
  stopSmelting(); stopCooking(); stopSmithing(); stopFishing(); stopCaveJob();
  if (chop.rec && chop.rec.state === 'standing') chop.rec.g.rotation.z = 0;
  if (chop.rec && ONLINE.act) setAct(null);
  chop.rec = null;
}
// what you are doing right now, shared with the others (chop, mine, smelt, fish)
function setAct(a){ ONLINE.act = a; writePresence(true); }
function clickNode(rec){
  if (rec.kind === 'npc' && rec.asleep) { showToast(`${rec.name} is fast asleep.`); return; }
  if (rec.onClick) { rec.onClick(rec); return; }   // the bonfire, its benches, raiders and gravestones handle their own clicks
  if (rec.state === 'felled') { showToast(`This ${rec.g && rec.g.userData ? rec.g.userData.name.toLowerCase() : 'node'} is gone for now. It will grow back soon.`); return; }
  if (rec.state === 'growing') { showToast('It is still growing back. Give it a moment.'); return; }
  if (rec.state === 'claiming') { showToast('Someone else is taking this right now.'); return; }
  if (rec.state !== 'standing') return;
  if (rec.kind === 'furnace' && smelting) return;   // already smelting: extra clicks do nothing
  cancelChop();
  if (rec.kind === 'anvil' && !hasTool('Hammer')) { showToast('You need a hammer to work the metal.'); return; }
  if (rec.kind === 'monster') { if (FIGHT && FIGHT.m !== rec && !(rec.delve && (DELVE || CAVE))) { showToast("You're already in combat!"); return; } startFight(rec); return; }   /* the cellar is multi-combat: clicking another creature switches to it */
  if (rec.kind === 'fish' && fishing) return;   // already fishing: extra clicks do nothing
  if (rec.kind === 'fish' && levelOf(SKILL_XP.Fishing) < FISHES[rec.fish].lvl) { showToast(`You need Fishing ${FISHES[rec.fish].lvl} to catch ${FISHES[rec.fish].word} here.`); return; }
  if (rec.kind === 'fish' && !hasTool(FISHES[rec.fish].tool)) { showToast(`You need ${FISHES[rec.fish].need} to fish here. Jory sells them, at his shack by the pond.`); return; }
  if (rec.kind === 'fish' && FISHES[rec.fish].bait && !hasItem(FISHES[rec.fish].bait)) { showToast(FISHES[rec.fish].noBait); return; }
  if (rec.kind === 'range' && !nextToCook()) { showToast(nothingToCookMsg()); return; }
  if (rec.kind === 'anvil' || rec.kind === 'npc' || rec.kind === 'fish' || rec.kind === 'door' || rec.kind === 'range' || rec.kind === 'animal') { /* no tool needed */ }
  else if (rec.kind === 'furnace') { if (!smeltKind()) { showToast(hasItem('Iron ore') ? 'You need Smithing 15 to smelt iron.' : 'Smelting needs copper ore and tin ore, or iron ore.'); return; } }
  else if (rec.kind === 'rock') { if (ORES[rec.ore].lvl && levelOf(SKILL_XP.Mining) < ORES[rec.ore].lvl) { showToast(`You need Mining ${ORES[rec.ore].lvl} to mine this rock.`); return; } if (!hasPick()) { showToast('You need a pickaxe to mine this rock.'); return; } }
  else if (!hasAxe()) { showToast('You need an axe to chop this tree.'); return; }
  if (rec.kind === 'door') {
    // approach from whichever side the adventurer is on
    const d2 = q => Math.hypot(q.x - hero.position.x, q.z - hero.position.z);
    const q = d2(rec.inside) < d2(rec.outside) ? rec.inside : rec.outside;
    walkStart(new THREE.Vector3(q.x, 0, q.z), () => toggleDoor(rec)); return;
  }
  if (rec.kind === 'tree' && levelOf(SKILL_XP.Woodcutting) < rec.level) { showToast(`You need Woodcutting ${rec.level} to chop this ${rec.g.userData.name.toLowerCase()}.`); return; }
  // stand on the side of the node that is free and nearest to the adventurer
  const spots = rec.talkAt ? [rec.talkAt] : [[2.4, 0], [-2.4, 0], [0, 2.4], [0, -2.4]]   /* a shopkeeper behind a counter is only talked to from the front */
    .map(([dx, dz]) => { const f = rec.kind === 'tree' ? 0.85 : 1; return { x: rec.x + dx * rec.s * f, z: rec.z + dz * rec.s * f }; })   /* trees: close enough for a level swing to bite */
    .filter(p => !blocked(p.x, p.z))
    .sort((a, b) => Math.hypot(a.x - hero.position.x, a.z - hero.position.z) - Math.hypot(b.x - hero.position.x, b.z - hero.position.z));
  if (!spots.length) return;
  walkStart(new THREE.Vector3(spots[0].x, 0, spots[0].z), () => { if (rec.kind === 'furnace') smelt(rec); else if (rec.kind === 'anvil') openSmithing(); else if (rec.kind === 'npc') openDialog(rec); else if (rec.kind === 'fish') catchFish(rec); else if (rec.kind === 'door') toggleDoor(rec); else if (rec.kind === 'range') cook(rec); else if (rec.kind === 'animal') petAnimal(rec); else { chop.rec = rec; chop.t = 0; setAct({ k: rec.kind === 'rock' ? 'mine' : 'chop', n: rec.key, t: Date.now() }); } });
}
// one copper ore and one tin ore make one bronze bar
function removeItem(name, which){
  if (name === 'Coins') { if (COINS <= 0) return false; COINS--; renderBag(); return true; }   /* coins live in their own purse, not a bag slot */
  const it = which && bag.includes(which) ? which : bag.find(i => i.name === name); if (!it) return false;
  if (--it.qty <= 0) bag.splice(bag.indexOf(it), 1);
  renderBag(); return true;
}
// smelting takes time: one bar every SMELT_MS, carrying on by itself while there is ore and room in the bag.
// Clicking the furnace again while it works does nothing, and walking away stops it.
const SMELT_MS = 2400;
let smelting = null;   // { rec, t0 } while a bar is in the furnace
const smeltKind = () => hasItem('Copper ore') && hasItem('Tin ore') ? 'bronze' : hasItem('Iron ore') && levelOf(SKILL_XP.Smithing) >= 15 ? 'iron' : null;
const SMELT_BAR = { bronze: 'Bronze bar', iron: 'Iron bar' };
const canSmelt = () => { const k = smeltKind(); return !!k && (bag.length < BAG_SIZE || hasItem(SMELT_BAR[k])); };
const ironChance = () => Math.min(1, 0.5 + (levelOf(SKILL_XP.Smithing) - 15) / 30 * 0.5);
function smelt(rec){
  if (smelting || cooking) return;
  if (!smeltKind()) { showToast(hasItem('Iron ore') ? 'You need Smithing 15 to smelt iron.' : 'Smelting needs copper ore and tin ore, or iron ore.'); return; }
  if (!canSmelt()) { showToast('Your bag is full.'); return; }   // check room before starting
  smelting = { rec, t0: performance.now() };
  setAct({ k: 'smelt', t: Date.now() });
  document.getElementById('smeltLabel').textContent = `Smelting ${smeltKind()}...`;
  document.getElementById('smeltBar').style.display = 'block';
}
// cooking: raw shrimp on a fireplace, one at a time; low levels burn some
const COOK_MS = 1900;
// everything that can go on the range: what it becomes, what it becomes if burnt, and the Cooking XP
const COOKS = {
  'Raw shrimp': { out: 'Shrimp', burnt: 'Burnt shrimp', xp: 30, word: 'shrimp', done: 'You cook the shrimp' },
  'Raw trout': { out: 'Trout', burnt: 'Burnt trout', xp: 40, lvl: 15, word: 'trout', done: 'You cook the trout' },
  'Raw bream': { out: 'Bream', burnt: 'Burnt bream', xp: 30, word: 'bream', done: 'You cook the bream' },   /* as in the phone game: 30 XP, no level needed */   /* as in the phone game: Cooking 15, 40 XP */
  'Raw chicken': { out: 'Cooked chicken', burnt: 'Burnt chicken', xp: 30, word: 'chicken', done: 'You roast the chicken' },
  'Raw beef': { out: 'Cooked beef', burnt: 'Burnt beef', xp: 35, word: 'beef', done: 'You cook the beef' },
  'Bread dough': { out: 'Bread', burnt: 'Burnt bread', xp: 40, word: 'bread', done: 'You bake a loaf of bread' },
};
const nextToCook = () => Object.keys(COOKS).find(n => hasItem(n) && levelOf(SKILL_XP.Cooking) >= (COOKS[n].lvl || 1)) || null;
// why there is nothing to cook: nothing raw at all, or only food that needs a better cook
function nothingToCookMsg(){ const n = Object.keys(COOKS).find(k => hasItem(k)); return n ? `You need Cooking ${COOKS[n].lvl} to cook ${COOKS[n].word}.` : 'You have nothing to cook.'; }
let cooking = null;
function cook(rec){
  if (cooking || smelting) return;
  if (!nextToCook()) { showToast(nothingToCookMsg()); return; }
  cooking = { rec, t0: performance.now() };
  setAct({ k: 'cook', t: Date.now() });
  document.getElementById('smeltLabel').textContent = 'Cooking...';
  document.getElementById('smeltBar').style.display = 'block';
}
function stopCooking(msg){
  if (!cooking) return;
  cooking = null; document.getElementById('smeltBar').style.display = 'none';
  if (ONLINE.act && ONLINE.act.k === 'cook') setAct(null);
  if (msg) showToast(msg);
}
function updateCook(){
  if (!cooking) return;
  const k = (performance.now() - cooking.t0) / COOK_MS;
  document.getElementById('smeltFill').style.width = Math.min(100, k * 100) + '%';
  if (hero) heroAnim.yaw = yawTo(hero.position.x, hero.position.z, cooking.rec.x, cooking.rec.z);
  heroAnim.mode = 'work';
  if (k < 1) return;
  const raw = nextToCook();
  if (!raw) { stopCooking(); return; }
  removeItem(raw);
  const c = COOKS[raw], burn = Math.max(0.02, 0.32 - 0.035 * (levelOf(SKILL_XP.Cooking) - (c.lvl || 1)));   // burns less the further past its level you are
  if (Math.random() < burn) { addItem(c.burnt, 1, ICON_FOR[c.burnt]); showToast(`Oops. You burn the ${c.word}.`); sizzleSound(true); }
  else { addItem(c.out, 1, ICON_FOR[c.out]); addXp('Cooking', c.xp); showToast(`${c.done} (${countOf(c.out)}).  +${c.xp} Cooking XP`); sizzleSound(false); }
  if (!nextToCook()) { stopCooking(); return; }
  cooking.t0 = performance.now(); setAct({ k: 'cook', t: Date.now() });
}
function sizzleSound(burnt){ sfx((ctx, t, out) => { out.gain.value = 0.5;   // a short sizzle with a couple of pops; burnt is harsher, with a smoky rumble
  nz(ctx, out, t, burnt ? 0.8 : 0.7, 'highpass', burnt ? 1700 : 3200, burnt ? 1500 : 3000, 0.7, 0.7, 0.01, burnt ? 0.7 : 0.55);
  for (let i = 0; i < 6; i++) nz(ctx, out, t + Math.random() * 0.5, 0.04, 'highpass', 2500, 2500, 0.7, 0.3 + Math.random() * 0.3, 0.001, 0.03);
  if (burnt) nz(ctx, out, t + 0.1, 0.6, 'lowpass', 380, 380, 0.7, 0.45, 0.1, 0.4); }); }
/* the phone game's eating sound, built into the page (no separate download), decoded once */
const EAT_MP3 = '';
let eatBuf = null, eatDecoding = false;
function loadEatSound(ctx){
  if (eatBuf || eatDecoding) return; eatDecoding = true;
  const bin = atob(EAT_MP3), bytes = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  ctx.decodeAudioData(bytes.buffer).then(b => { eatBuf = b; }).catch(() => {});
}
function eatSound(){
  const ctx = audio(); if (!ctx) return; const t = ctx.currentTime;
  loadEatSound(ctx);
  if (eatBuf) { const src = ctx.createBufferSource(); src.buffer = eatBuf; src.connect(sfxOut(ctx)); src.start(t); return; }
  /* until it has been decoded (the very first bite), the old made-in-code chewing */
  for (let i = 0; i < 3; i++) { const src = ctx.createBufferSource(); src.buffer = noiseBuffer(ctx, 0.08);
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 900 + i * 150; bp.Q.value = 2;
    const g = ctx.createGain(); g.gain.setValueAtTime(0.3, t + i * 0.16); g.gain.exponentialRampToValueAtTime(0.001, t + i * 0.16 + 0.08);
    src.connect(bp); bp.connect(g); g.connect(sfxOut(ctx)); src.start(t + i * 0.16); src.stop(t + i * 0.16 + 0.1); }
}
function stopSmelting(msg){
  if (!smelting) return;
  smelting = null;
  document.getElementById('smeltBar').style.display = 'none';
  if (ONLINE.act && ONLINE.act.k === 'smelt') setAct(null);
  if (msg) showToast(msg);
}
function updateSmelt(){
  if (!smelting) return;
  const k = (performance.now() - smelting.t0) / SMELT_MS;
  document.getElementById('smeltFill').style.width = Math.min(100, k * 100) + '%';
  if (hero) heroAnim.yaw = yawTo(hero.position.x, hero.position.z, smelting.rec.x, smelting.rec.z);
  heroAnim.mode = 'work';
  if (k < 1) return;
  // the bar is done: the ores go in, a bar comes out
  const kind = smeltKind();
  if (!kind) { stopSmelting('You have run out of ore.'); return; }
  smeltSound();
  if (kind === 'bronze') { removeItem('Copper ore'); removeItem('Tin ore'); addItem('Bronze bar', 1, BAR_ICON); addXp('Smithing', 6.25); showToast(`You smelt a bronze bar (${barCount()} in your bag).  +6.25 Smithing XP`); }
  else { removeItem('Iron ore');
    if (Math.random() < ironChance()) { addItem('Iron bar', 1, IRON_BAR_ICON); addXp('Smithing', 12.5); showToast(`You smelt an iron bar (${barCount('Iron bar')} in your bag).  +12.5 Smithing XP`); }
    else showToast('The ore is too impure, and the iron is lost.'); }
  if (!smeltKind()) { stopSmelting(); return; }
  document.getElementById('smeltLabel').textContent = `Smelting ${smeltKind()}...`;
  if (!canSmelt()) { stopSmelting('Your bag is full.'); return; }
  smelting.t0 = performance.now();   // the next bar goes in
  setAct({ k: 'smelt', t: Date.now() });
}
